INSERT INTO `AdmissionPages` VALUES (1,'admission',NULL,'<h2><span style=\"color: rgb(164, 56, 83);\"><strong>Admission</strong></span><strong> </strong><span style=\"color: rgb(50, 34, 109);\"><strong>Procedure</strong></span></h2><p>At <strong>Translam Institute of Pharmaceutical Education &amp; Research (TIPER)</strong>, we follow a <strong>transparent and student-centric admission process</strong> designed to help aspiring pharmacy professionals begin their academic journey with clarity, ease, and confidence.</p><p>We welcome students from diverse educational backgrounds who are passionate about science, healthcare, and innovation. Our admission team provides <strong>complete guidance at every stage</strong>from initial inquiry and document assistance to counseling and final enrollmentensuring a smooth and supportive experience for every applicant.</p><p><span style=\"color: rgb(0, 0, 0);\"><strong>Steps to Apply:</strong></span></p><ol><li><p><strong>Online/Offline Registration:</strong>Candidates can register online through our official website or visit the campus to collect the admission form.</p></li><li><p><strong>Eligibility Check:</strong>Each course has specific eligibility criteria. Applicants must ensure they meet the academic and age requirements before applying.</p></li><li><p><strong>Document Submission:</strong>Submit the required documents, including academic certificates, ID proof, photographs, and any other relevant documents either online or at the admission office.</p></li><li><p><strong>Counseling &amp; Interaction:</strong>Our faculty or counselors will conduct a personal interaction or counseling session to help candidates select the right course based on their interests and goals.</p></li><li><p><strong>Confirmation &amp; Fee Payment:</strong>Once shortlisted, candidates will receive an admission offer. To confirm the seat, the required fee must be paid within the given deadline.</p></li><li><p><strong>Enrollment:</strong>Upon successful payment and verification, students will receive an official admission confirmation and student ID.</p></li></ol><h4><span style=\"color: rgb(232, 48, 48);\"><strong>Important Notes:</strong></span></h4><ul><li><p>Admission is granted on a first-come, first-served basis for most programs.</p></li><li><p>Some courses may require entrance tests or interviews.</p></li><li><p>Scholarships and financial aid are available for eligible students.</p></li></ul><p>For detailed admission dates, course-specific eligibility, and fee structures, please visits. our <strong>Admissions Office</strong> or contact us directly.</p><h2><span style=\"color: rgb(164, 56, 83);\"><strong>Eligibility for&nbsp;</strong></span><span style=\"color: rgb(50, 34, 109);\"><strong>Admission</strong></span></h2><p><strong>B.Pharm (Bachelor of Pharmacy)</strong></p><ul><li><p>Candidates must have passed the Intermediate Examination of U.P. Board or 10+2 (or equivalent) from a recognized Board/University.</p></li><li><p>Must secure a minimum of <strong>50% marks (General &amp; OBC)</strong> or <strong>45% marks (SC/ST)</strong> in aggregate in the subject group <strong>PCB or PCM</strong>.</p></li><li><p><strong>Lateral Entry (Second Year):</strong></p><ul><li><p><strong>2nd Year:</strong> Admission through <strong>CUET</strong> or <strong>AKTU Entrance Exam</strong>.</p></li></ul></li><li><p><strong>Entrance exam merit list</strong> will be followed for final selection.</p></li><li><p>Vacant seats are filled by the college as per AKTU guidelines.</p></li></ul><hr><p></p><p><strong>M.Pharm (Master of Pharmacy)</strong></p><ul><li><p>Candidates must hold a <strong>B.Pharm degree</strong> from a recognized university.</p></li><li><p>Admission preference:</p><ol><li><p><strong>First preference</strong>  Candidates with a valid <strong>GPAT score</strong>.</p></li><li><p><strong>Second preference</strong>  Candidates without GPAT score.</p></li></ol></li><li><p>Eligibility:</p><ul><li><p><strong>General &amp; OBC candidates</strong>: Minimum <strong>60% marks</strong> in B.Pharm.</p></li><li><p><strong>SC/ST candidates</strong>: Minimum <strong>55% marks</strong> in B.Pharm.</p></li></ul></li><li><p>Admissions are carried out as follows:</p><ul><li><p><strong>50% seats</strong> through <strong>AKTU, Lucknow</strong> norms.</p></li><li><p><strong>50% seats</strong> through the <strong>Translam Group Entrance Examination</strong> (as per prescribed criteria).</p></li></ul></li></ul><hr><p></p><p><strong>D.Pharm (Diploma in Pharmacy)</strong></p><ul><li><p>Candidates must have passed <strong>10+2 (Science stream)</strong> from a recognized Board/University with <strong>PCM or PCB</strong> as main subjects.</p></li><li><p>A minimum of <strong>50% aggregate marks</strong> is required.</p></li><li><p>Admissions are based on the guidelines of the <strong>Board of Technical Education (BTE), Lucknow</strong>.</p></li></ul><hr><p></p><p><strong>For Admission Enquiry</strong></p><p>=Þ Call: <strong>9105555630, 9105555632</strong><br>=ç Email: <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" href=\"mailto:pharma@translam.com\"><strong>pharma@translam.com</strong></a></p><p></p>','2025-08-08 01:47:31','2025-12-01 16:09:59','/uploads/1760547460928-admission-banner.jpg');
/*!40000 ALTER TABLE `AdmissionPages` ENABLE KEYS */;
UNLOCK TABLES;

