INSERT INTO `DirectorDesks` VALUES (1,'PRINCIPLE MESSAGE','data:image/jpeg;base64,','Translam Group: Empowering Futures for 38 Glorious Years','<p>Welcome to <strong>Translam Institute of Pharmaceutical Education &amp; Research (TIPER)</strong>, a premier institution of the Translam Group dedicated to shaping skilled, knowledgeable, and ethically driven pharmacy professionals. Since its inception, TIPER has been committed to excellence in pharmaceutical education, research, and community health services.</p><p>At TIPER, we offer a dynamic and progressive learning environment designed to meet the ever-evolving demands of the pharmaceutical industry. Our mission is to build strong academic foundations through state-of-the-art infrastructure, modern laboratories, innovative teaching methodologies, and a highly qualified faculty team. We aim to nurture competent pharmacists who can contribute significantly to healthcare, research, and the nations socio-economic growth.</p><p>In addition to classroom learning, we actively promote community outreach and public health awareness through medical camps, health counseling sessions, and collaborations with healthcare agencies. These initiatives ensure that our students understand the true essence of the pharmacy professionservice to society.</p><p>I warmly welcome all aspiring students who wish to build a rewarding career in the pharmaceutical sciences. Together, let us strive for excellence, innovation, and service to humanity. I also extend my heartfelt gratitude to all stakeholders, faculty members, parents, and well-wishers for their unwavering support in advancing the vision and mission of TIPER.</p>','[{\"name\":\"Dr. Nasir \",\"title\":\"Principle\",\"image\":\"data:image/png;base64,\"}]','2025-08-10 07:52:18','2025-12-08 16:29:42');
/*!40000 ALTER TABLE `DirectorDesks` ENABLE KEYS */;
UNLOCK TABLES;

