INSERT INTO `OurSuccesses` VALUES (1,'Our Success (TIPER)','','<p style=\"text-align: center;\">At <strong>Translam Institute of Pharmaceutical Education &amp; Research (TIPER)</strong>, success is defined by the excellence of our students, the groundbreaking research they contribute, and the positive impact they create in the healthcare and pharmaceutical industry. Over the years, TIPER has built a strong legacy of academic brilliance, advanced laboratory training, industry collaborations, and a commitment to innovation.</p><p style=\"text-align: center;\">Our graduates are contributing significantly in pharmaceutical companies, research organizations, hospitals, and healthcare institutions across India and abroad. With a focus on <strong>quality education, practical learning, and professional growth</strong>, TIPER takes pride in shaping pharmacy professionals who advance healthcare, ensure drug safety, and drive scientific progress.</p>','[{\"graduates\":\"5000+\",\"graduatesLabel\":\"Successful Pharmacy Graduates\",\"alumni\":\"5000+\",\"alumniLabel\":\"Alumni working across Pharma & Healthcare \",\"yearsExcellence\":\"38+\",\"yearsExcellenceLabel\":\"Years of Excellence in Pharmaceutical Education\",\"recruiters\":\"80+\",\"recruitersLabel\":\"Industry Collaborations & Recruiters\",\"placementRate\":\"100%+\",\"placementRateLabel\":\"Placement Success Rate\"}]','2025-08-10 08:16:54','2025-11-27 10:16:05');
/*!40000 ALTER TABLE `OurSuccesses` ENABLE KEYS */;
UNLOCK TABLES;

