/*!40000 ALTER TABLE `Placements` DISABLE KEYS */;
INSERT INTO `Placements` VALUES (1,'Placements','/uploads/1760547531239-WhatsApp Image 2025-10-11 at 12.41.56 (18).jpeg','Corporate Resource Center (CRC) ','<p>At <strong>Translam Institute of Pharmaceutical Education &amp; Research (TIPER)</strong>, the <strong>Corporate Resource Center (CRC)</strong> plays a pivotal role in connecting the institute with the pharmaceutical and healthcare industries. Functioning under the direct guidance of the Institute Director, the CRC acts as a strategic bridge that fosters industry collaboration, academic enrichment, and career advancement for students.</p>','<p>With the dedicated efforts of our faculty and the consistent performance of our students, <strong>TIPER has established a strong reputation among recruiters</strong> as a leading pharmacy institute in the NCR region. The CRC ensures smooth coordination of campus placements, internship opportunities, industrial visits, and expert interaction sessions.</p><p>To support the holistic growth of students, the <strong>Personality Development Cell (PDC)</strong> focuses on improving communication, confidence, leadership abilities, and critical thinkingqualities essential for success in the pharmaceutical and healthcare sectors.</p><p>Our IndustryInstitute collaborations encourage the exchange of knowledge, resources, and innovations. These partnerships enhance academic learning by helping students understand real-world challenges, emerging technologies, regulatory trends, and practical problem-solving techniques. Students also gain valuable exposure through industry-supervised projects and training modules designed by experts.</p><p>Beyond academics, TIPER emphasizes overall personality grooming through sports, co-curricular activities, and professional development programs. The inclusion of additional skill-based sessions, technical training, and optional foreign-language learning helps students build global competencies and readiness for diverse work environments.</p>','Training and Development','<p>At Translam Institute, we strongly believe in continuous growth and skill enhancement. Our Training and Development Cell is committed to shaping students into industry-ready professionals by bridging the gap between academic knowledge and practical application. </p>','[{\"id\":\"1\",\"title\":\"Pedagogical Skill Development:\",\"description\":\"Hands-on training in modern teaching methodologies, classroom management, and the use of digital tools for effective learning.\",\"order\":0},{\"id\":\"2\",\"title\":\"Soft Skills and Personality Enhancement\",\"description\":\"Sessions on communication, presentation, teamwork, and time management.\",\"order\":1},{\"id\":\"3\",\"title\":\"Aptitude & Interview Preparation\",\"description\":\"Regular workshops, mock interviews, and mentorship programs to equip students for teaching careers, competitive exams, and campus placements.\",\"order\":2},{\"id\":\"4\",\"title\":\"School & Industry Connect Programs\",\"description\":\"Educational workshops, guest lectures, internships, and field visits in collaboration with reputed schools and educational organizations.\",\"order\":3}]','[{\"id\":\"1\",\"name\":\"Mohd Kafil\",\"company\":\"HBM in Cipla Pharmaceutical\",\"image\":\"/uploads/1764604279665-image1.jpeg\",\"order\":0,\"isActive\":true},{\"id\":\"2\",\"name\":\"Mohd Shadab\",\"company\":\"BE in Zydus Healthcare.\",\"image\":\"/uploads/1764604300610-image2.jpeg\",\"order\":1,\"isActive\":true},{\"id\":\"3\",\"name\":\"Mohd Azharuddin\",\"company\":\"ABM in Natco Pharma.\",\"image\":\"/uploads/1764604318062-image3.jpeg\",\"order\":2,\"isActive\":true},{\"id\":\"4\",\"name\":\"Nawazish\",\"company\":\"Sales Executive in Sun Pharma Laboratories Pvt.\",\"image\":\"/uploads/1764604343434-image4.jpeg\",\"order\":3,\"isActive\":true},{\"id\":\"5\",\"name\":\"Mohd Nadeem\",\"company\":\"Area Business Manager in NOVA\",\"image\":\"/uploads/1764604382333-image6.jpeg\",\"order\":4,\"isActive\":true},{\"id\":\"6\",\"name\":\"Anas Choudhary\",\"company\":\"Business Executive in  in Mediflorence\",\"image\":\"/uploads/1764604454136-image8.jpeg\",\"order\":5,\"isActive\":true}]','2025-08-11 04:49:24','2025-12-01 15:58:54');
/*!40000 ALTER TABLE `Placements` ENABLE KEYS */;
UNLOCK TABLES;

