INSERT INTO `Testimonials` VALUES (2,'Gloria Rose','Student','','/uploads/1754849378065-student1.webp','Thank you so much for your help. It\'s exactly what I\'ve been looking for. You won\'t regret it. It really saves me time and effort. TOTC is exactly what our business has been lacking. ghgg',5,1,'2025-08-10 15:09:00','2025-08-10 18:09:40'),(3,'Alex Smith','Student','','/uploads/1754849389166-girl-img.webp','TOTC helped me organize my study schedule and improved my grades. Highly recommended!',5,1,'2025-08-10 15:09:00','2025-08-10 18:09:51'),(4,'Priya Patel','Student','','/images/testimonial-slide1.png','The tools for teachers and students are fantastic. My classroom is more productive than ever.',5,1,'2025-08-10 15:09:00','2025-08-10 15:09:00');
