INSERT INTO `WhyChooseUs` VALUES (1,'Why Choose TIPER ?','','<p>Everything you can do in a physical classroom, you can now do  and more  with TIPER.</p>','[{\"id\":\"1\",\"title\":\"Academic Excellence\",\"subtitle\":\"PHARMACEUTICAL EDUCATION & RESEARCH\",\"description\":\"We deliver quality pharmaceutical education through advanced curriculum, state-of-the-art laboratories, and industry-oriented programs. Students gain both theoretical knowledge and practical exposure.\",\"tags\":[\"Research-Oriented Learning\",\"Modern Labs & Infrastructure\",\"Global Exposure\"],\"order\":0,\"isActive\":true},{\"id\":\"2\",\"title\":\"Experienced Faculty\",\"subtitle\":\"EXPERT GUIDANCE\",\"description\":\"Our faculty members are highly qualified professionals, researchers, and industry experts who bring real-world experience and deep academic knowledge to the classroom.\",\"tags\":[\"Mentorship & Guidance\",\"Research Experts\",\"PhD Holders\"],\"order\":1,\"isActive\":true},{\"id\":\"3\",\"title\":\"Career Opportunities\",\"subtitle\":\"PLACEMENTS & INTERNSHIPS\",\"description\":\"We prepare students for successful careers in the pharmaceutical and healthcare industries by connecting them with leading recruiters and offering structured placement training.\",\"tags\":[\"Top Recruiters\",\"Internships\",\"Placement Training\"],\"order\":2,\"isActive\":true}]','2025-08-10 08:18:35','2025-08-24 12:09:35');
/*!40000 ALTER TABLE `WhyChooseUs` ENABLE KEYS */;
UNLOCK TABLES;

